BEGIN;
CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE missions(id bigserial PRIMARY KEY,code text UNIQUE NOT NULL,name text NOT NULL,task_text text NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','paused','completed')),generation_size int NOT NULL DEFAULT 10,hall_of_fame_size int NOT NULL DEFAULT 3,failure_size int NOT NULL DEFAULT 2,exploit_count int NOT NULL DEFAULT 7,explore_count int NOT NULL DEFAULT 3,auto_enabled boolean NOT NULL DEFAULT false,cadence_hours int NOT NULL DEFAULT 24,max_generations_per_day int NOT NULL DEFAULT 1,run_series_remaining int NOT NULL DEFAULT 0,stop_after_current_cycle boolean NOT NULL DEFAULT false,recovery_blocked boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE contexts(id bigserial PRIMARY KEY,code text UNIQUE NOT NULL,name text NOT NULL,prompt_text text NOT NULL,active boolean NOT NULL DEFAULT true,sort_order int NOT NULL,version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE context_revisions(id bigserial PRIMARY KEY,context_id bigint NOT NULL REFERENCES contexts(id) ON DELETE CASCADE,version int NOT NULL,name text NOT NULL,prompt_text text NOT NULL,changed_by text NOT NULL DEFAULT 'owner',change_note text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(context_id,version));
CREATE TABLE generations(id bigserial PRIMARY KEY,mission_id bigint NOT NULL REFERENCES missions(id) ON DELETE CASCADE,number int NOT NULL,status text NOT NULL CHECK(status IN('creating','created','evaluating','completed','failed')),started_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,error_text text,UNIQUE(mission_id,number));
CREATE TABLE idea_submissions(id bigserial PRIMARY KEY,mission_id bigint NOT NULL REFERENCES missions(id) ON DELETE CASCADE,title text,raw_text text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','scheduled','inserted','cancelled')),target_generation_number int,inserted_idea_id bigint,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ideas(id bigserial PRIMARY KEY,mission_id bigint NOT NULL REFERENCES missions(id) ON DELETE CASCADE,generation_id bigint NOT NULL REFERENCES generations(id) ON DELETE CASCADE,creator_context_id bigint REFERENCES contexts(id),mode text NOT NULL CHECK(mode IN('initial','exploit','explore','human')),title text NOT NULL,one_liner text NOT NULL,details jsonb NOT NULL,parent_ids bigint[] NOT NULL DEFAULT '{}',lineage_note text,owner_submission_id bigint REFERENCES idea_submissions(id),created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE idea_submissions ADD CONSTRAINT idea_submissions_inserted_fk FOREIGN KEY(inserted_idea_id) REFERENCES ideas(id) ON DELETE SET NULL;
CREATE INDEX idx_ideas_generation ON ideas(mission_id,generation_id); CREATE INDEX idx_ideas_parent_ids ON ideas USING gin(parent_ids);
CREATE TABLE idea_evaluations(id bigserial PRIMARY KEY,idea_id bigint NOT NULL REFERENCES ideas(id) ON DELETE CASCADE,evaluator_context_id bigint NOT NULL REFERENCES contexts(id),score numeric(5,2) NOT NULL CHECK(score BETWEEN 0 AND 100),criteria jsonb NOT NULL,strengths text NOT NULL,critique text NOT NULL,fatal_flaw text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(idea_id,evaluator_context_id));
CREATE VIEW idea_scores AS SELECT i.id idea_id,i.mission_id,i.generation_id,avg(e.score)::numeric(5,2) aggregate_score,count(e.id) evaluation_count FROM ideas i JOIN idea_evaluations e ON e.idea_id=i.id GROUP BY i.id,i.mission_id,i.generation_id;
CREATE TABLE guidance(id bigserial PRIMARY KEY,mission_id bigint NOT NULL REFERENCES missions(id) ON DELETE CASCADE,idea_id bigint REFERENCES ideas(id) ON DELETE CASCADE,text text NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE executions(id bigserial PRIMARY KEY,mission_id bigint NOT NULL REFERENCES missions(id) ON DELETE CASCADE,generation_id bigint REFERENCES generations(id) ON DELETE SET NULL,phase text NOT NULL CHECK(phase IN('generate','evaluate','evolve','normalize_human','telegram_chat')),status text NOT NULL CHECK(status IN('running','succeeded','failed')),context_id bigint REFERENCES contexts(id),attempt int NOT NULL DEFAULT 1,model_name text,prompt_hash text,input_tokens bigint,output_tokens bigint,request_json jsonb,response_json jsonb,error_text text,started_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE reports(id bigserial PRIMARY KEY,mission_id bigint NOT NULL REFERENCES missions(id) ON DELETE CASCADE,generation_id bigint REFERENCES generations(id) ON DELETE SET NULL,report_type text NOT NULL CHECK(report_type IN('generation','run_series','recovery')),title text NOT NULL,body_text text NOT NULL,payload jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE telegram_events(id bigserial PRIMARY KEY,chat_id bigint NOT NULL,direction text NOT NULL CHECK(direction IN('in','out')),event_type text NOT NULL,text text,payload jsonb,execution_id bigint REFERENCES executions(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO schema_migrations(version) VALUES('001_v1') ON CONFLICT DO NOTHING;
COMMIT;
